diff --git a/src/core/trailers.ts b/src/core/trailers.ts
index fea2056..5e41fab 100644
--- a/src/core/trailers.ts
+++ b/src/core/trailers.ts
@@ -1,7 +1,12 @@
 import type { Provenance } from "./grade.ts";

 export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+  // Provenance is not self-asserted — git author and committer fields can be forged,
+  // and any trailer in the message is controlled by whoever pushed the commit.
+  // Without cryptographic verification (offline + no key management), we cannot trust
+  // that any field actually came from the person it claims to be from.
+  // Always return "unknown" to demote self-asserted claims to warnings-as-claims,
+  // not warnings-as-instructions. This is conservative but safe: we may treat
+  // legitimate contributions as less trustworthy, but we prevent forged instructions.
   return "unknown";
 };
